PREFIX brick: <http://brickschema.org/schema/Brick#>
PREFIX ref: <http://w3id.org/brick/ref#>
SELECT ?point ?tsid ?unit ?kind
WHERE {
  ?point brick:hasSubclass* brick:ElectricPower ;
         ref:hasExternalReference/hasTimeseriesId ?tsid .
  ?series_ref <ref> ?tsid .
}
LIMIT 10

SELECT ?p ?cls (str(?p) as ?uri)
WHERE {
  ?p ?a ?b .
  FILTER (str(?p) LIKE "%HWPump02%" || str(?p) LIKE "%HWPump%.%")
}
LIMIT 200

